sources.benchmark:
use std::{
    error::Error,
    fs,
    hint::black_box,
    io::{BufRead, BufReader, Write},
    path::PathBuf,
    sync::Arc,
    time::Instant,
};

use arrow::{
    array::{Array, ArrayRef, Decimal128Array, Float32Array, Float64Array, Int64Array},
    datatypes::{DataType, Field, Schema},
    record_batch::RecordBatch,
    util::display::array_value_to_string,
};
use datafusion::{
    datasource::MemTable,
    execution::SessionStateBuilder,
    physical_plan::{ExecutionPlan, displayable, execute_stream},
    prelude::{SessionConfig, SessionContext},
};
use futures_util::StreamExt;
use sail_plan::decimal_null::SparkDecimalNullPropagation;
use sail_plan::{config::PlanConfig, physical_plan::SparkQueryPlanner, resolver::PlanResolver};
use serde_json::{Value, json};

type Result<T> = std::result::Result<T, Box<dyn Error + Send + Sync>>;

const ROWS: usize = 1_048_576;
const BATCH_SIZE: usize = 8192;
const WARMUPS: usize = 2;
const SAMPLES: usize = 9;

// In-memory projection only. Measure Delta I/O and concurrent queries separately.
fn input(precision: u8, scale: i8, divisor_scale: i8, nulls: bool) -> Result<MemTable> {
    let data_type = |scale| {
        if precision == 0 {
            DataType::Float64
        } else {
            DataType::Decimal128(precision, scale)
        }
    };
    let schema = Arc::new(Schema::new(vec![
        Field::new("a", data_type(scale), nulls),
        Field::new("b", data_type(divisor_scale), nulls),
    ]));
    let mut batches = Vec::new();
    for start in (0..ROWS).step_by(BATCH_SIZE) {
        let columns = [false, true]
            .into_iter()
            .map(|divisor| -> Result<ArrayRef> {
                let scale = if divisor { divisor_scale } else { scale };
                let values = (start..(start + BATCH_SIZE).min(ROWS)).map(|i| {
                    let period = if divisor { 13 } else { 10 };
                    if nulls && i % period == period - 1 {
                        None
                    } else if divisor {
                        Some((i % 97 + 3) as i128)
                    } else {
                        Some((i % 10000 + 2) as i128)
                    }
                });
                Ok(if precision == 0 {
                    Arc::new(Float64Array::from_iter(
                        values.map(|v| v.map(|v| v as f64 / 100.0)),
                    ))
                } else {
                    let unit = 10_i128.pow((scale - if scale >= 35 { 5 } else { 2 }) as u32);
                    Arc::new(
                        Decimal128Array::from_iter(values.map(|v| v.map(|v| v * unit)))
                            .with_precision_and_scale(precision, scale)?,
                    )
                })
            })
            .collect::<Result<Vec<_>>>()?;
        batches.push(RecordBatch::try_new(schema.clone(), columns)?);
    }
    Ok(MemTable::try_new(schema, vec![batches])?)
}

async fn consume(ctx: &SessionContext, plan: Arc<dyn ExecutionPlan>) -> Result<(usize, usize)> {
    let mut stream = execute_stream(plan, ctx.task_ctx())?;
    let (mut rows, mut nulls) = (0, 0);
    while let Some(batch) = stream.next().await {
        let batch = batch?;
        rows += batch.num_rows();
        nulls += batch.column(0).null_count();
        black_box(batch);
    }
    Ok((rows, nulls))
}

// perf stat --delay=-1 --control=fifo:DIR/control,DIR/ack
// Counting covers the enabled phase and the control handshake.
fn perf_command(command: &[u8]) -> Result<()> {
    if let Some(dir) = std::env::var_os("DECIMAL_BENCH_PERF_DIR") {
        let dir = PathBuf::from(dir);
        fs::OpenOptions::new()
            .write(true)
            .open(dir.join("control"))?
            .write_all(command)?;
        let mut ack = String::new();
        BufReader::new(fs::File::open(dir.join("ack"))?).read_line(&mut ack)?;
        if ack != "ack\n" {
            return Err("unexpected perf control acknowledgement".into());
        }
    }
    Ok(())
}

async fn plan_query(ctx: &SessionContext, sql: &str, ansi: bool) -> Result<Arc<dyn ExecutionPlan>> {
    let mut config = PlanConfig::default();
    config.ansi_mode = ansi;
    config.session_timezone = "UTC".into();
    let ast = sail_sql_analyzer::parser::parse_one_statement(sql)?;
    let spec = sail_sql_analyzer::statement::from_ast_statement(ast)?;
    let named = PlanResolver::new(ctx, Arc::new(config))
        .resolve_named_plan(spec)
        .await?;
    let frame = ctx.execute_logical_plan(named.plan).await?;
    Ok(frame.create_physical_plan().await?)
}

// Keep normal SQL optimization enabled: a short IN list may become comparisons
// or a constant and never reach the generic physical filter.
async fn generic_in_bench(
    ctx: &SessionContext,
    output: &str,
    selected: Option<&str>,
    check_only: bool,
) -> Result<()> {
    use arrow::array::{BooleanArray, StringArray};

    let phase = std::env::var("DECIMAL_BENCH_PERF_PHASE").unwrap_or_else(|_| "execution".into());
    if !matches!(phase.as_str(), "planning" | "execution") {
        return Err("DECIMAL_BENCH_PERF_PHASE must be planning or execution".into());
    }
    let timing_count = |name: &str, default: usize| -> Result<usize> {
        let count = match std::env::var(name) {
            Ok(value) => value.parse()?,
            Err(std::env::VarError::NotPresent) => default,
            Err(error) => return Err(error.into()),
        };
        if count == 0 {
            return Err(format!("{name} must be positive").into());
        }
        Ok(count)
    };
    // Generic IN only: keep fresh plans per sample while allowing longer runs.
    let warmups = timing_count("DECIMAL_BENCH_IN_WARMUPS", WARMUPS)?;
    let samples = timing_count("DECIMAL_BENCH_IN_SAMPLES", SAMPLES)?;
    let mut results = Vec::new();
    for (family, profiles) in [
        (
            "utf8",
            &[
                "low",
                "high",
                "nullable",
                "all_null",
                "long_list",
                "nullable_long_list",
                "filter",
                "not_in",
            ][..],
        ),
        ("long_utf8", &["low", "high", "nullable"][..]),
        ("decimal", &["low", "high", "nullable", "long_list"][..]),
        ("boolean", &["low", "nullable"][..]),
        (
            "float",
            &[
                "zero_single",
                "zero_pair",
                "zero_short",
                "zero_long_list",
                "zero_nullable",
                "zero_not_in",
                "zero_filter",
                "zero_wide",
                "nan_short",
            ][..],
        ),
        (
            "double",
            &[
                "long_list",
                "nullable_long_list",
                "zero_single",
                "zero_pair",
                "zero_short",
                "zero_long_list",
                "zero_nullable",
                "zero_not_in",
                "zero_filter",
                "zero_wide",
                "nan_short",
            ][..],
        ),
    ] {
        for &profile in profiles {
            let case = format!("generic_in_{family}_{profile}");
            if selected.is_some_and(|s| s != case) {
                continue;
            }
            let nullable = matches!(
                profile,
                "nullable"
                    | "all_null"
                    | "nullable_long_list"
                    | "not_in"
                    | "zero_nullable"
                    | "zero_not_in"
            );
            let zero_list = profile.starts_with("zero_");
            let nan_list = profile == "nan_short";
            let float_value = |v: usize| match v {
                0 if zero_list || nan_list => 0.0,
                1 if zero_list || nan_list => -0.0,
                2 if zero_list || nan_list => f64::NAN,
                3 if zero_list || nan_list => -f64::NAN,
                4 if zero_list || nan_list => f64::from_bits(0x7ff0_0000_0000_0123),
                5 if zero_list || nan_list => f64::from_bits(0xfff0_0000_0000_0123),
                6 if zero_list || nan_list => -1.25,
                _ => v as f64,
            };
            let length = if matches!(profile, "all_null" | "zero_single") {
                1
            } else if family == "boolean" || profile == "zero_pair" {
                2
            } else if profile.ends_with("long_list") {
                128
            } else {
                3
            };
            let domain = if profile == "high" {
                3
            } else if family == "boolean" {
                2
            } else if profile == "long_list" {
                997
            } else {
                97
            };
            let prefix = if family == "long_utf8" {
                "x".repeat(240)
            } else {
                String::new()
            };
            let text = |v| format!("{prefix}value{v}");
            let value = |i| {
                let id = subquery_input_id(i);
                if nullable && id % 3 == 0 {
                    None
                } else {
                    Some(id % domain + usize::from(profile == "high"))
                }
            };
            let (data_type, sql_type) = match family {
                "utf8" | "long_utf8" => (DataType::Utf8, "STRING"),
                "decimal" => (DataType::Decimal128(18, 2), "DECIMAL(18,2)"),
                "boolean" => (DataType::Boolean, "BOOLEAN"),
                "float" => (
                    DataType::Float32,
                    if profile == "zero_wide" {
                        "DOUBLE"
                    } else {
                        "FLOAT"
                    },
                ),
                "double" => (DataType::Float64, "DOUBLE"),
                _ => unreachable!(),
            };
            let schema = Arc::new(Schema::new(vec![
                Field::new("id", DataType::Int64, false),
                Field::new("v", data_type, nullable),
            ]));
            let mut batches = Vec::new();
            for start in (0..ROWS).step_by(BATCH_SIZE) {
                let positions = start..(start + BATCH_SIZE).min(ROWS);
                let values = positions.clone().map(value);
                let array: ArrayRef = match family {
                    "utf8" | "long_utf8" => {
                        Arc::new(StringArray::from_iter(values.map(|v| v.map(text))))
                    }
                    "decimal" => Arc::new(
                        Decimal128Array::from_iter(values.map(|v| v.map(|n| n as i128 * 100)))
                            .with_precision_and_scale(18, 2)?,
                    ),
                    "boolean" => Arc::new(BooleanArray::from_iter(
                        values.map(|v| v.map(|n| n % 2 != 0)),
                    )),
                    "float" => Arc::new(Float32Array::from_iter(
                        values.map(|v| v.map(|n| float_value(n) as f32)),
                    )),
                    "double" => {
                        Arc::new(Float64Array::from_iter(values.map(|v| v.map(float_value))))
                    }
                    _ => unreachable!(),
                };
                batches.push(RecordBatch::try_new(
                    schema.clone(),
                    vec![
                        Arc::new(Int64Array::from_iter_values(positions.map(|i| i as i64))),
                        array,
                    ],
                )?);
            }
            ctx.deregister_table("generic_in_input")?;
            ctx.register_table(
                "generic_in_input",
                Arc::new(MemTable::try_new(schema, vec![batches])?),
            )?;
            let first = usize::from(!zero_list);
            let members = (first..first + length - usize::from(nullable) - usize::from(nan_list))
                .collect::<Vec<_>>();
            let mut literals = members
                .iter()
                .map(|&n| {
                    let literal = match family {
                        "utf8" | "long_utf8" => format!("'{}'", text(n)),
                        "boolean" => (n % 2 != 0).to_string(),
                        _ => n.to_string(),
                    };
                    format!("CAST({literal} AS {sql_type})")
                })
                .collect::<Vec<_>>();
            if nullable {
                literals.push(format!("CAST(NULL AS {sql_type})"));
            }
            if nan_list {
                literals.push(format!("CAST('NaN' AS {sql_type})"));
            }
            let negated = matches!(profile, "not_in" | "zero_not_in");
            let filter = matches!(profile, "filter" | "zero_filter");
            let predicate = format!(
                "v {}IN ({})",
                if negated { "NOT " } else { "" },
                literals.join(",")
            );
            let sql = if filter {
                format!("SELECT id AS r FROM generic_in_input WHERE {predicate}")
            } else {
                format!("SELECT {predicate} AS r FROM generic_in_input")
            };
            let expected = (0..ROWS)
                .map(|i| {
                    value(i).and_then(|v| {
                        let found = if family == "boolean" {
                            members.iter().any(|n| n % 2 == v % 2)
                        } else if matches!(family, "float" | "double") {
                            (nan_list && float_value(v).is_nan())
                                || members.iter().any(|&n| float_value(v) == n as f64)
                        } else {
                            members.contains(&v)
                        };
                        if found {
                            Some(!negated)
                        } else if nullable {
                            None
                        } else {
                            Some(negated)
                        }
                    })
                })
                .collect::<Vec<_>>();
            let expected_ids = (0..ROWS)
                .filter(|&i| expected[i] == Some(true))
                .collect::<Vec<_>>();
            for ansi in [true, false] {
                let plan = plan_query(ctx, &sql, ansi).await?;
                let physical_plan = displayable(plan.as_ref()).indent(true).to_string();
                let output_type = if filter {
                    DataType::Int64
                } else {
                    DataType::Boolean
                };
                assert_eq!(plan.schema().fields().len(), 1);
                assert_eq!(plan.schema().field(0).data_type(), &output_type);
                let mut stream = execute_stream(plan, ctx.task_ctx())?;
                let (mut rows, mut nulls) = (0, 0);
                while let Some(batch) = stream.next().await {
                    let batch = batch?;
                    if filter {
                        let array = batch
                            .column(0)
                            .as_any()
                            .downcast_ref::<Int64Array>()
                            .unwrap();
                        for actual in array.iter() {
                            assert_eq!(
                                actual,
                                Some(*expected_ids.get(rows).ok_or("too many filter rows")? as i64)
                            );
                            rows += 1;
                        }
                    } else {
                        let array = batch
                            .column(0)
                            .as_any()
                            .downcast_ref::<BooleanArray>()
                            .unwrap();
                        for actual in array.iter() {
                            assert_eq!(Some(&actual), expected.get(rows), "{case}, row {rows}");
                            rows += 1;
                        }
                    }
                    nulls += batch.column(0).null_count();
                }
                assert_eq!(rows, if filter { expected_ids.len() } else { ROWS });
                let mut result = json!({
                    "id": format!("{case}_ansi{ansi}"), "sql": sql, "ansi": ansi,
                    "physical_plan": physical_plan, "validated_rows": rows, "output_nulls": nulls,
                    "matching_inputs": expected_ids.len(), "list_length": length,
                    "input_domain": domain, "string_prefix_bytes": prefix.len(),
                });
                // Both ANSI modes are validated. Timing uses ANSI on only;
                // this workload has no failing casts or arithmetic.
                if !check_only && ansi {
                    for _ in 0..warmups {
                        assert_eq!(
                            consume(ctx, plan_query(ctx, &sql, ansi).await?).await?,
                            (rows, nulls)
                        );
                    }
                    let (mut plans, mut planning_ms, mut execution_ms) =
                        (Vec::new(), Vec::new(), Vec::new());
                    if phase == "planning" {
                        perf_command(b"enable\n")?;
                    }
                    for _ in 0..samples {
                        let start = Instant::now();
                        plans.push(plan_query(ctx, &sql, ansi).await?);
                        planning_ms.push(start.elapsed().as_secs_f64() * 1000.0);
                    }
                    if phase == "planning" {
                        perf_command(b"disable\n")?;
                    }
                    if phase == "execution" {
                        perf_command(b"enable\n")?;
                    }
                    for plan in plans {
                        let start = Instant::now();
                        let counts = consume(ctx, plan).await?;
                        execution_ms.push(start.elapsed().as_secs_f64() * 1000.0);
                        assert_eq!(counts, (rows, nulls));
                    }
                    if phase == "execution" {
                        perf_command(b"disable\n")?;
                    }
                    result["planning_samples_ms"] = json!(planning_ms);
                    result["samples_ms"] = json!(execution_ms);
                }
                results.push(result);
            }
        }
    }
    if results.is_empty() {
        return Err("no benchmark case matched CASE_ID".into());
    }
    fs::write(
        output,
        serde_json::to_vec_pretty(&json!({
            "rows": ROWS, "batch_size": BATCH_SIZE, "partitions": 1,
            "input_permutation": "(position * 4099 + 17) % rows",
            "warmups": warmups, "samples": samples, "check_only": check_only,
            "perf_phase": phase, "results": results,
        }))?,
    )?;
    Ok(())
}

fn subquery_input_id(position: usize) -> usize {
    position.wrapping_mul(4099).wrapping_add(17) % ROWS
}

// Permuted outer rows make a missing ORDER BY observable. Half the keys have no
// inner group; every eighth inner group has only NULL x values.
fn register_subquery_inputs(ctx: &SessionContext) -> Result<usize> {
    let integer_types = [
        ("i8", DataType::Int8),
        ("i16", DataType::Int16),
        ("i32", DataType::Int32),
    ];
    let mut fields = vec![
        Field::new("id", DataType::Int64, false),
        Field::new("k", DataType::Int64, false),
        Field::new("a", DataType::Decimal128(18, 4), false),
        Field::new("f32", DataType::Float32, false),
        Field::new("f64", DataType::Float64, false),
    ];
    for (name, data_type) in &integer_types {
        fields.push(Field::new(format!("{name}_a"), data_type.clone(), true));
        fields.push(Field::new(format!("{name}_b"), data_type.clone(), true));
    }
    let schema = Arc::new(Schema::new(fields));
    let mut batches = Vec::new();
    for start in (0..ROWS).step_by(BATCH_SIZE) {
        let ids = (start..(start + BATCH_SIZE).min(ROWS)).map(|i| subquery_input_id(i) as i64);
        let mut columns: Vec<ArrayRef> = vec![
            Arc::new(Int64Array::from_iter_values(ids.clone())),
            Arc::new(Int64Array::from_iter_values(ids.clone().map(|i| i % 512))),
            Arc::new(
                Decimal128Array::from_iter_values(
                    ids.clone().map(|i| i128::from(i % 97 + 2) * 100),
                )
                .with_precision_and_scale(18, 4)?,
            ),
            Arc::new(Float32Array::from_iter_values(
                ids.clone()
                    .map(|i| ((i % 97 + 2) as f64 / 100.0 + 0.125) as f32),
            )),
            Arc::new(Float64Array::from_iter_values(
                ids.clone().map(|i| (i % 97 + 2) as f64 / 100.0 + 0.125),
            )),
        ];
        let a = Int64Array::from_iter(ids.clone().map(|i| (i % 10 != 9).then_some(i % 97 - 48)));
        let b = Int64Array::from_iter(ids.map(|i| (i % 13 != 12).then_some(i % 7 + 1)));
        for (_, data_type) in &integer_types {
            columns.push(arrow::compute::cast(&a, data_type)?);
            columns.push(arrow::compute::cast(&b, data_type)?);
        }
        batches.push(RecordBatch::try_new(schema.clone(), columns)?);
    }
    ctx.register_table(
        "bench_outer",
        Arc::new(MemTable::try_new(schema, vec![batches])?),
    )?;
    let keys = (0_i64..256)
        .flat_map(|k| std::iter::repeat_n(k, (1 + k % 3) as usize))
        .collect::<Vec<_>>();
    let inner_rows = keys.len();
    let schema = Arc::new(Schema::new(vec![
        Field::new("k", DataType::Int64, false),
        Field::new("x", DataType::Decimal128(18, 4), true),
        Field::new("d", DataType::Decimal128(18, 4), false),
    ]));
    let batch = RecordBatch::try_new(
        schema.clone(),
        vec![
            Arc::new(Int64Array::from_iter_values(keys.iter().copied())),
            Arc::new(
                Decimal128Array::from_iter(
                    keys.iter()
                        .map(|k| (k % 8 != 0).then_some(i128::from(k + 1) * 10_000)),
                )
                .with_precision_and_scale(18, 4)?,
            ),
            Arc::new(
                Decimal128Array::from_iter_values(std::iter::repeat_n(40_000, inner_rows))
                    .with_precision_and_scale(18, 4)?,
            ),
        ],
    )?;
    ctx.register_table(
        "bench_inner",
        Arc::new(MemTable::try_new(schema, vec![vec![batch]])?),
    )?;
    Ok(inner_rows)
}

fn expected_subquery_value(case: &str, id: usize) -> Option<i128> {
    let key = id % 512;
    let count = if key < 256 { 1 + key % 3 } else { 0 };
    match case {
        "no_division" | "round_wide" => Some(id as i128 * 1_000_000),
        "round_decimal" => Some((id % 97 + 2) as i128 * 10_000),
        "div_integer" | "div_decimal" => Some((id / 4) as i128 * 1_000_000),
        "div_column" => Some((id / (key + 1)) as i128 * 1_000_000),
        "div_i8_column" | "div_i16_column" | "div_i32_column" | "div_i8_literal"
        | "div_i16_literal" | "div_i32_literal" => {
            let a = (id % 10 != 9).then_some((id % 97) as i128 - 48);
            let b = if case.ends_with("_literal") {
                Some(3)
            } else {
                (id % 13 != 12).then_some((id % 7 + 1) as i128)
            };
            a.zip(b).map(|(a, b)| a / b * 1_000_000)
        }
        "negative_literal" => Some((id % 97 + 2) as i128 * -2_500),
        "wide_projection" | "plain_projection" | "plain_sorted" | "scalar_projection"
        | "scalar_sorted" => Some((id % 97 + 2) as i128 * 2_500),
        "correlated_max" => (key < 256 && key % 8 != 0).then_some((key + 1) as i128 * 250_000),
        "correlated_count" | "nested_lateral" => Some(count as i128 * 250_000),
        "chained_lateral" => Some((count + 1 + count % 3) as i128 * 250_000),
        "left_lateral" => (count > 1).then_some(count as i128 * 250_000),
        "null_divide_left"
        | "null_divide_right"
        | "div_null_cast_values"
        | "div_null_cast_column"
        | "div_null_cast_numeric" => None,
        "div_constant" => Some(3_000_000),
        "compare_f32_column" | "compare_f64_column" => Some(1_000_000),
        "float_compare_f32" | "float_compare_f64" => Some(i128::from(id % 97 + 2 >= 38) * 1_000_000),
        "float_compare_mixed" => {
            let value = (id % 97 + 2) as f64 / 100.0 + 0.125;
            Some(i128::from(f64::from(value as f32) > value) * 1_000_000)
        }
        "float_in_f32" | "float_in_f64" => Some(i128::from(matches!(id % 97, 23 | 48 | 73)) * 1_000_000),
        "float_in_dynamic" => Some(1_000_000),
        "float_projected_in" => Some(i128::from(key < 256) * 1_000_000),
        "compare_f64_literal" => Some(i128::from(id % 97 + 2 >= 38) * 1_000_000),
        "compare_decimal_literal" => Some(i128::from(id % 97 + 2 <= 50) * 1_000_000),
        "in_f32_short"
        | "in_f64_short"
        | "in_decimal_short"
        | "in_decimal_explicit_double"
        | "in_integer" => Some(i128::from(matches!(id % 97, 23 | 48 | 73)) * 1_000_000),
        "in_f64_long" => Some(i128::from(id % 97 == 23) * 1_000_000),
        "in_f64_nulls" => {
            (id % 4 != 0).then_some(i128::from(matches!(id % 97, 23 | 48 | 73)) * 1_000_000)
        }
        "in_f64_not_null" => matches!(id % 97, 23 | 48 | 73).then_some(0),
        "in_f64_dynamic" => Some(i128::from(id % 2 == 0 || id % 97 == 23) * 1_000_000),
        "projected_exists" | "projected_in" => Some(i128::from(key < 256) * 1_000_000),
        "projected_not_exists" | "projected_not_in" => Some(i128::from(key >= 256) * 1_000_000),
        "projected_nullable" | "projected_mixed" => {
            (key < 256 && key % 8 != 0).then_some(1_000_000)
        }
        "projected_correlated_in" => {
            if key >= 256 {
                Some(0)
            } else {
                (key % 8 != 0).then_some(1_000_000)
            }
        }
        _ => unreachable!("unknown benchmark case"),
    }
}

async fn validate_subquery(
    ctx: &SessionContext,
    plan: Arc<dyn ExecutionPlan>,
    case: &str,
    sorted: bool,
) -> Result<(usize, usize, i128)> {
    if plan.schema().fields().len() != 1
        || plan.schema().field(0).data_type() != &DataType::Decimal128(38, 6)
    {
        return Err(format!("unexpected result schema: {:?}", plan.schema()).into());
    }
    let mut stream = execute_stream(plan, ctx.task_ctx())?;
    let (mut rows, mut nulls, mut sum) = (0, 0, 0);
    while let Some(batch) = stream.next().await {
        let batch = batch?;
        let values = batch
            .column(0)
            .as_any()
            .downcast_ref::<Decimal128Array>()
            .unwrap();
        for actual in values.iter() {
            if rows >= ROWS {
                return Err("too many output rows".into());
            }
            let id = if sorted {
                rows
            } else {
                subquery_input_id(rows)
            };
            let expected = expected_subquery_value(case, id);
            if actual != expected {
                return Err(format!("row {rows}: expected {expected:?}, got {actual:?}").into());
            }
            rows += 1;
            nulls += usize::from(actual.is_none());
            sum += actual.unwrap_or(0);
        }
    }
    if rows != ROWS {
        return Err(format!("expected {ROWS} rows, got {rows}").into());
    }
    Ok((rows, nulls, sum))
}

async fn subquery_bench(
    ctx: &SessionContext,
    output: &str,
    selected: Option<&str>,
    check_only: bool,
) -> Result<()> {
    let inner_rows = register_subquery_inputs(ctx)?;
    let phase = std::env::var("DECIMAL_BENCH_PERF_PHASE").unwrap_or_else(|_| "execution".into());
    if phase != "planning" && phase != "execution" {
        return Err("DECIMAL_BENCH_PERF_PHASE must be planning or execution".into());
    }
    let retention = std::env::var("DECIMAL_BENCH_RETAIN").unwrap_or_else(|_| "none".into());
    if !matches!(retention.as_str(), "none" | "batch" | "all" | "released") {
        return Err("DECIMAL_BENCH_RETAIN must be none, batch, all or released".into());
    }
    let divisor = "(SELECT min(d) FROM bench_inner)";
    let count = "SELECT count(*) AS n FROM bench_inner i WHERE i.k=o.k";
    let cases = [
        (
            "no_division",
            "CAST(o.id AS DECIMAL(38,6))".to_owned(),
            "".to_owned(),
            false,
        ),
        (
            "plain_projection",
            "o.a / CAST(4 AS DECIMAL(18,4))".into(),
            "".into(),
            false,
        ),
        (
            "wide_projection",
            "o.a / CAST(4 AS DECIMAL(38,34))".into(),
            "".into(),
            false,
        ),
        (
            "negative_literal",
            "o.a / CAST(-4 AS DECIMAL(18,4))".into(),
            "".into(),
            false,
        ),
        ("round_decimal", "ROUND(o.a, 2)".into(), "".into(), false),
        ("div_integer", "o.id DIV 4".into(), "".into(), false),
        ("float_compare_f32", "CAST(o.f32 > CAST(0.5 AS FLOAT) AS INT)".into(), "".into(), false),
        ("float_compare_f64", "CAST(o.f64 > CAST(0.5 AS DOUBLE) AS INT)".into(), "".into(), false),
        ("float_compare_mixed", "CAST(o.f32 > o.f64 AS INT)".into(), "".into(), false),
        ("float_in_f32", "CAST(o.f32 IN (CAST(0.375 AS FLOAT),CAST(0.625 AS FLOAT),CAST(0.875 AS FLOAT)) AS INT)".into(), "".into(), false),
        ("float_in_f64", "CAST(o.f64 IN (CAST(0.375 AS DOUBLE),CAST(0.625 AS DOUBLE),CAST(0.875 AS DOUBLE)) AS INT)".into(), "".into(), false),
        ("float_in_dynamic", "CAST(o.f32 IN (CAST(o.f64 AS FLOAT),CAST(0.5 AS FLOAT)) AS INT)".into(), "".into(), false),
        ("float_projected_in", "CAST(CAST(o.k AS FLOAT) IN (SELECT CAST(i.k AS DOUBLE) FROM bench_inner i) AS INT)".into(), "".into(), false),
        ("compare_f32_column", "CAST(o.f32 > o.a AS INT)".into(), "".into(), false),
        ("compare_f64_column", "CAST(o.f64 > o.a AS INT)".into(), "".into(), false),
        ("compare_f64_literal", "CAST(o.f64 >= 0.5 AS INT)".into(), "".into(), false),
        ("compare_decimal_literal", "CAST(o.a < CAST(0.505 AS DOUBLE) AS INT)".into(), "".into(), false),
        ("in_f32_short", "CAST(o.f32 IN (0.375,0.625,0.875) AS INT)".into(), "".into(), false),
        ("in_f64_short", "CAST(o.f64 IN (0.375,0.625,0.875) AS INT)".into(), "".into(), false),
        ("in_decimal_short", "CAST(o.a IN (CAST(0.25 AS DOUBLE),CAST(0.5 AS DOUBLE),CAST(0.75 AS DOUBLE)) AS INT)".into(), "".into(), false),
        ("in_decimal_explicit_double", "CAST(CAST(o.a AS DOUBLE) IN (CAST(0.25 AS DOUBLE),CAST(0.5 AS DOUBLE),CAST(0.75 AS DOUBLE)) AS INT)".into(), "".into(), false),
        ("in_integer", "CAST(o.id % 97 IN (23,48,73) AS INT)".into(), "".into(), false),
        ("in_f64_long", format!("CAST(o.f64 IN ({}) AS INT)", (0..128).map(|i| format!("{i}.375")).collect::<Vec<_>>().join(",")), "".into(), false),
        ("in_f64_nulls", "CAST((CASE WHEN o.id % 4 != 0 THEN o.f64 END) IN (0.375,0.625,0.875) AS INT)".into(), "".into(), false),
        ("in_f64_not_null", "CAST(o.f64 NOT IN (0.375,0.625,0.875,NULL) AS INT)".into(), "".into(), false),
        ("in_f64_dynamic", "CAST(o.f64 IN (o.a,CASE WHEN o.id % 2 = 0 THEN o.f64 ELSE CAST(0.375 AS DOUBLE) END) AS INT)".into(), "".into(), false),
        ("projected_exists", "CAST(EXISTS (SELECT 1 FROM bench_inner i WHERE i.k=o.k) AS INT)".into(), "".into(), false),
        ("projected_not_exists", "CAST(NOT EXISTS (SELECT 1 FROM bench_inner i WHERE i.k=o.k) AS INT)".into(), "".into(), false),
        ("projected_in", "CAST(o.k IN (SELECT i.k FROM bench_inner i) AS INT)".into(), "".into(), false),
        ("projected_not_in", "CAST(o.k NOT IN (SELECT i.k FROM bench_inner i) AS INT)".into(), "".into(), false),
        ("projected_nullable", "CAST(o.k IN (SELECT i.x-1 FROM bench_inner i) AS INT)".into(), "".into(), false),
        ("projected_mixed", "CAST(CAST(o.k AS DOUBLE) IN (SELECT i.x-1 FROM bench_inner i) AS INT)".into(), "".into(), false),
        ("projected_correlated_in", "CAST(o.k IN (SELECT i.x-1 FROM bench_inner i WHERE i.k=o.k) AS INT)".into(), "".into(), false),
        ("div_constant", "CAST(7 AS INT) DIV CAST(2 AS INT)".into(), "".into(), false),
        (
            "div_null_cast_values",
            "t.q".into(),
            "CROSS JOIN (SELECT CAST(NULL AS INT) DIV CAST(v AS INT) AS q FROM VALUES ('2') t(v)) t".into(),
            false,
        ),
        (
            "div_null_cast_column",
            "CAST(NULL AS INT) DIV CAST(o.id AS INT)".into(),
            "".into(),
            false,
        ),
        (
            "div_null_cast_numeric",
            "t.q".into(),
            "CROSS JOIN (SELECT CAST(NULL AS INT) DIV CAST(v AS INT) AS q FROM VALUES (CAST('2.5' AS DOUBLE)) t(v)) t".into(),
            false,
        ),
        (
            "div_decimal",
            "CAST(o.id AS DECIMAL(18,2)) DIV CAST(4 AS DECIMAL(18,2))".into(),
            "".into(),
            false,
        ),
        ("div_column", "o.id DIV (o.k + 1)".into(), "".into(), false),
        (
            "div_i8_column",
            "o.i8_a DIV o.i8_b".into(),
            "".into(),
            false,
        ),
        (
            "div_i8_literal",
            "o.i8_a DIV CAST(3 AS TINYINT)".into(),
            "".into(),
            false,
        ),
        (
            "div_i16_column",
            "o.i16_a DIV o.i16_b".into(),
            "".into(),
            false,
        ),
        (
            "div_i16_literal",
            "o.i16_a DIV CAST(3 AS SMALLINT)".into(),
            "".into(),
            false,
        ),
        (
            "div_i32_column",
            "o.i32_a DIV o.i32_b".into(),
            "".into(),
            false,
        ),
        (
            "div_i32_literal",
            "o.i32_a DIV CAST(3 AS INT)".into(),
            "".into(),
            false,
        ),
        (
            "round_wide",
            "ROUND(CAST(o.id AS DECIMAL(38,4)), 2)".into(),
            "".into(),
            false,
        ),
        (
            "plain_sorted",
            "o.a / CAST(4 AS DECIMAL(18,4))".into(),
            "".into(),
            true,
        ),
        (
            "scalar_projection",
            format!("o.a / {divisor}"),
            "".into(),
            false,
        ),
        ("scalar_sorted", format!("o.a / {divisor}"), "".into(), true),
        (
            "null_divide_left",
            format!("CAST(NULL AS DECIMAL(18,4)) / {divisor}"),
            "".into(),
            false,
        ),
        (
            "null_divide_right",
            format!("{divisor} / CAST(NULL AS DECIMAL(18,4))"),
            "".into(),
            false,
        ),
        (
            "correlated_max",
            format!("(SELECT max(i.x) / {divisor} FROM bench_inner i WHERE i.k=o.k)"),
            "".into(),
            true,
        ),
        (
            "correlated_count",
            format!(
                "(SELECT CAST(count(*) AS DECIMAL(18,4)) / {divisor} FROM bench_inner i WHERE i.k=o.k)"
            ),
            "".into(),
            true,
        ),
        (
            "nested_lateral",
            format!("CAST(t.n AS DECIMAL(18,4)) / {divisor}"),
            format!("CROSS JOIN LATERAL (SELECT z.n FROM ({count}) z) t"),
            true,
        ),
        (
            "chained_lateral",
            format!("CAST(t.n + u.m AS DECIMAL(18,4)) / {divisor}"),
            format!(
                "CROSS JOIN LATERAL ({count}) t CROSS JOIN LATERAL (SELECT count(*) AS m FROM bench_inner j WHERE j.k=t.n) u"
            ),
            true,
        ),
        (
            "left_lateral",
            format!("CAST(t.n AS DECIMAL(18,4)) / {divisor}"),
            format!("LEFT JOIN LATERAL ({count}) t ON t.n>1"),
            true,
        ),
    ];
    let mut results = Vec::new();
    for (case, expression, join, sorted) in cases {
        let order = if sorted { "ORDER BY o.id" } else { "" };
        let sql = format!(
            "SELECT CAST({expression} AS DECIMAL(38,6)) AS r FROM bench_outer o {join} {order}"
        );
        for ansi in [true, false] {
            let id = format!("{case}_ansi{ansi}");
            if selected.is_some_and(|s| s != id) {
                continue;
            }
            let mut result = json!({"id": id, "sql": sql, "ansi": ansi, "sorted": sorted});
            let plan = match plan_query(ctx, &sql, ansi).await {
                Ok(plan) => plan,
                Err(error) if check_only => {
                    result["status"] = json!("planning_error");
                    result["error"] = json!(error.to_string());
                    results.push(result);
                    continue;
                }
                Err(error) => return Err(error),
            };
            result["physical_plan"] = json!(displayable(plan.as_ref()).indent(true).to_string());
            let (rows, nulls, sum) = match validate_subquery(ctx, plan, case, sorted).await {
                Ok(counts) => counts,
                Err(error) if check_only => {
                    result["status"] = json!("validation_error");
                    result["error"] = json!(error.to_string());
                    results.push(result);
                    continue;
                }
                Err(error) => return Err(error),
            };
            result["status"] = json!("ok");
            result["validated_rows"] = json!(rows);
            result["output_nulls"] = json!(nulls);
            result["coefficient_sum"] = json!(sum.to_string());
            if !check_only {
                let mut retained = Vec::new();
                if retention != "none" {
                    let held_plan = plan_query(
                        ctx,
                        "SELECT CAST(id AS DECIMAL(38,6)) AS r FROM bench_outer",
                        true,
                    )
                    .await?;
                    let mut stream = execute_stream(held_plan, ctx.task_ctx())?;
                    while let Some(batch) = stream.next().await {
                        retained.push(batch?);
                        if retention != "all" {
                            break;
                        }
                    }
                    drop(stream);
                    assert_eq!(
                        validate_retained(&retained),
                        if retention == "all" { ROWS } else { BATCH_SIZE }
                    );
                    // Dropping the first result on another thread must release
                    // its owner and make the reuse slot available again.
                    if retention == "released" {
                        std::thread::spawn(move || drop(retained)).join().unwrap();
                        retained = Vec::new();
                    }
                }
                // Inspect a uniquely owned value buffer outside timing. This
                // distinguishes native allocation from a custom reuse owner.
                if std::env::var_os("DECIMAL_BENCH_RETAIN").is_some() {
                    result["retention"] = json!(retention);
                    result["retained_rows"] = json!(validate_retained(&retained));
                    let input = Int64Array::from_iter_values(0..BATCH_SIZE as i64);
                    let cast = arrow::compute::cast(&input, &DataType::Decimal128(38, 6))?;
                    let values = cast
                        .as_any()
                        .downcast_ref::<Decimal128Array>()
                        .unwrap()
                        .clone();
                    drop(cast);
                    let (_, values, _) = values.into_parts();
                    result["probe_value_buffer_mutable"] =
                        json!(values.into_inner().into_mutable().is_ok());
                }
                for _ in 0..WARMUPS {
                    let plan = plan_query(ctx, &sql, ansi).await?;
                    assert_eq!(consume(ctx, plan).await?, (rows, nulls));
                }
                // Every execution gets a fresh physical plan. ScalarSubqueryExec
                // and hash joins otherwise retain results from their first run.
                let mut plans = Vec::new();
                let mut planning_ms = Vec::new();
                if phase == "planning" {
                    perf_command(b"enable\n")?;
                }
                for _ in 0..SAMPLES {
                    let start = Instant::now();
                    let plan = plan_query(ctx, &sql, ansi).await?;
                    planning_ms.push(start.elapsed().as_secs_f64() * 1000.0);
                    plans.push(plan);
                }
                if phase == "planning" {
                    perf_command(b"disable\n")?;
                }
                let mut execution_ms = Vec::new();
                if phase == "execution" {
                    perf_command(b"enable\n")?;
                }
                for plan in &plans {
                    let start = Instant::now();
                    let counts = consume(ctx, plan.clone()).await?;
                    execution_ms.push(start.elapsed().as_secs_f64() * 1000.0);
                    assert_eq!(counts, (rows, nulls));
                }
                if phase == "execution" {
                    perf_command(b"disable\n")?;
                }
                result["planning_samples_ms"] = json!(planning_ms);
                result["samples_ms"] = json!(execution_ms);
                assert_eq!(
                    validate_retained(&retained),
                    match retention.as_str() {
                        "batch" => BATCH_SIZE,
                        "all" => ROWS,
                        _ => 0,
                    }
                );
            }
            eprintln!("{id}: validated {rows} rows, {nulls} NULLs");
            results.push(result);
        }
    }
    if results.is_empty() {
        return Err("no benchmark case matched CASE_ID".into());
    }
    fs::write(
        output,
        serde_json::to_vec_pretty(&json!({
            "rows": ROWS, "inner_rows": inner_rows, "batch_size": BATCH_SIZE, "partitions": 1,
            "input_permutation": "(position * 4099 + 17) % rows",
            "warmups": WARMUPS, "samples": SAMPLES, "check_only": check_only,
            "perf_phase": phase, "results": results,
        }))?,
    )?;
    Ok(())
}

fn validate_retained(batches: &[RecordBatch]) -> usize {
    let mut rows = 0;
    for batch in batches {
        let values = batch
            .column(0)
            .as_any()
            .downcast_ref::<Decimal128Array>()
            .unwrap();
        assert_eq!(values.data_type(), &DataType::Decimal128(38, 6));
        for value in values.iter() {
            assert_eq!(value, Some(subquery_input_id(rows) as i128 * 1_000_000));
            rows += 1;
        }
    }
    rows
}

async fn cast_bench(ctx: &SessionContext, output: &str, selected: Option<&str>) -> Result<()> {
    let mut results = Vec::new();
    for nulls in [false, true] {
        ctx.deregister_table("bench_input")?;
        ctx.register_table("bench_input", Arc::new(input(18, 4, 4, nulls)?))?;
        // Prepare converted input arrays outside the measured cast.
        for (table, data_type) in [
            ("bench_strings", "VARCHAR"),
            ("bench_float32", "REAL"),
            ("bench_float64", "DOUBLE"),
        ] {
            ctx.deregister_table(table)?;
            let frame = ctx
                .sql(&format!(
                    "SELECT CAST(a AS {data_type}) AS a FROM bench_input"
                ))
                .await?;
            let schema = Arc::new(frame.schema().as_arrow().clone());
            ctx.register_table(
                table,
                Arc::new(MemTable::try_new(schema, vec![frame.collect().await?])?),
            )?;
        }
        for (kind, table, precision, scale) in [
            ("narrow", "bench_input", 10, 2),
            ("widen", "bench_input", 38, 4),
            ("string", "bench_strings", 18, 4),
            ("float32", "bench_float32", 18, 4),
            ("float64", "bench_float64", 18, 4),
        ] {
            let sql = format!("SELECT CAST(a AS DECIMAL({precision},{scale})) AS r FROM {table}");
            for ansi in [true, false] {
                let id = format!("cast_{kind}_nulls{nulls}_ansi{ansi}");
                if selected.is_some_and(|s| s != id) {
                    continue;
                }
                let plan = plan_query(ctx, &sql, ansi).await?;
                let mut stream = execute_stream(plan.clone(), ctx.task_ctx())?;
                let (mut rows, mut output_nulls, mut coefficient_sum) = (0, 0, 0_i128);
                while let Some(batch) = stream.next().await {
                    let batch = batch?;
                    let values = batch
                        .column(0)
                        .as_any()
                        .downcast_ref::<Decimal128Array>()
                        .ok_or("expected Decimal128 output")?;
                    assert_eq!(values.data_type(), &DataType::Decimal128(precision, scale));
                    for value in values.iter() {
                        let expected = if nulls && rows % 10 == 9 {
                            None
                        } else {
                            Some((rows % 10000 + 2) as i128 * 10_i128.pow((scale - 2) as u32))
                        };
                        assert_eq!(value, expected, "{id}, row {rows}");
                        rows += 1;
                        output_nulls += usize::from(value.is_none());
                        coefficient_sum += value.unwrap_or(0);
                    }
                }
                assert_eq!(rows, ROWS);
                for _ in 0..WARMUPS {
                    assert_eq!(consume(ctx, plan.clone()).await?, (rows, output_nulls));
                }
                let mut samples_ms = Vec::new();
                perf_command(b"enable\n")?;
                for _ in 0..SAMPLES {
                    let start = Instant::now();
                    let counts = consume(ctx, plan.clone()).await?;
                    samples_ms.push(start.elapsed().as_secs_f64() * 1000.0);
                    assert_eq!(counts, (rows, output_nulls));
                }
                perf_command(b"disable\n")?;
                eprintln!("{id}: validated {rows} rows, {output_nulls} NULLs");
                results.push(json!({
                    "id": id, "sql": sql, "validated_rows": rows,
                    "output_nulls": output_nulls, "coefficient_sum": coefficient_sum.to_string(),
                    "output_nullable": plan.schema().field(0).is_nullable(),
                    "output_type": format!("{:?}", plan.schema().field(0).data_type()),
                    "physical_plan": displayable(plan.as_ref()).indent(true).to_string(),
                    "samples_ms": samples_ms,
                }));
            }
        }
    }
    if results.is_empty() {
        return Err("no benchmark case matched CASE_ID".into());
    }
    fs::write(
        output,
        serde_json::to_vec_pretty(&json!({
            "rows": ROWS, "batch_size": BATCH_SIZE, "partitions": 1,
            "warmups": WARMUPS, "samples": SAMPLES, "results": results,
        }))?,
    )?;
    Ok(())
}

#[tokio::main(flavor = "current_thread")]
async fn main() -> Result<()> {
    if cfg!(debug_assertions) {
        return Err("use cargo build --release for timing".into());
    }
    let args = std::env::args().collect::<Vec<_>>();
    let output = args
        .get(1)
        .ok_or("usage: decimal_bench OUTPUT_JSON [SUITE [CASE_ID]]")?;
    let ctx = SessionContext::new_with_state(
        SessionStateBuilder::new()
            .with_default_features()
            .with_analyzer_rule(Arc::new(SparkDecimalNullPropagation))
            .with_config(
                SessionConfig::new()
                    .with_batch_size(BATCH_SIZE)
                    .with_target_partitions(1),
            )
            .with_query_planner(Arc::new(SparkQueryPlanner))
            .build(),
    );
    let inputs = match args.get(2).map(String::as_str) {
        Some(mode @ ("generic-in" | "generic-in-check")) => {
            return generic_in_bench(
                &ctx,
                output,
                args.get(3).map(String::as_str),
                mode == "generic-in-check",
            )
            .await;
        }
        Some("casts") => return cast_bench(&ctx, output, args.get(3).map(String::as_str)).await,
        Some(mode @ ("subqueries" | "subquery-check")) => {
            return subquery_bench(
                &ctx,
                output,
                args.get(3).map(String::as_str),
                mode == "subquery-check",
            )
            .await;
        }
        None | Some("normal") => vec![
            (10, 2, 2, false),
            (18, 4, 4, false),
            (38, 6, 6, false),
            (10, 2, 2, true),
            (0, 2, 2, false),
        ],
        Some("float") => vec![(0, 2, 2, false), (0, 2, 2, true)],
        Some("high-scale") => vec![(38, 35, 35, false), (38, 38, 38, false), (38, 38, 38, true)],
        Some("high-scale-35") => vec![(38, 35, 35, false)],
        // Scale 6 still needs the fallback after shifting; scale 7 just fits i256.
        Some("high-scale-mixed") => vec![(38, 6, 38, false), (38, 7, 38, false), (38, 6, 38, true)],
        Some(_) => {
            return Err(
                "expected normal, float, high-scale, high-scale-35, high-scale-mixed, subqueries, subquery-check, generic-in, generic-in-check or casts"
                    .into(),
            );
        }
    };
    let mut results = Vec::new();
    for (precision, scale, divisor_scale, nulls) in inputs {
        ctx.deregister_table("bench_input")?;
        ctx.register_table(
            "bench_input",
            Arc::new(input(precision, scale, divisor_scale, nulls)?),
        )?;
        for divisor_kind in [
            "column",
            "typed_literal",
            "integer_literal",
            "numerator_literal",
        ] {
            if divisor_kind == "numerator_literal" && precision != 0 {
                continue;
            }
            if divisor_kind == "integer_literal" && (nulls || precision == 0 || divisor_scale >= 35)
            {
                continue;
            }
            let numerator_scalar = divisor_kind == "numerator_literal";
            let scalar = !matches!(divisor_kind, "column" | "numerator_literal");
            let denominator = if !scalar {
                "b".to_owned()
            } else if divisor_kind == "integer_literal" {
                "3".to_owned()
            } else if precision == 0 {
                "CAST(3 AS DOUBLE)".to_owned()
            } else if divisor_scale >= 35 {
                format!("CAST('0.3' AS DECIMAL({precision},{divisor_scale}))")
            } else {
                format!("CAST(3 AS DECIMAL({precision},{divisor_scale}))")
            };
            let numerator = if numerator_scalar {
                "CAST(3 AS DOUBLE)"
            } else {
                "a"
            };
            let sql = format!("SELECT {numerator} / {denominator} AS quotient FROM bench_input");
            let expected_nulls = (0..ROWS)
                .filter(|i| {
                    nulls && ((!numerator_scalar && i % 10 == 9) || (!scalar && i % 13 == 12))
                })
                .count();
            for ansi in [true, false] {
                let divisor_id = if scale == divisor_scale {
                    String::new()
                } else {
                    format!("_divisor_s{divisor_scale}")
                };
                let id = format!(
                    "p{precision}_s{scale}{divisor_id}_nulls{nulls}_{divisor_kind}_ansi{ansi}"
                );
                if args.get(3).is_some_and(|selected| selected != &id) {
                    continue;
                }
                let plan = plan_query(&ctx, &sql, ansi).await?;
                let physical_plan = displayable(plan.as_ref()).indent(true).to_string();
                let mut stream = execute_stream(plan.clone(), ctx.task_ctx())?;
                let first = stream.next().await.ok_or("missing first batch")??;
                let first_values = (0..3)
                    .map(|i| array_value_to_string(first.column(0).as_ref(), i))
                    .collect::<std::result::Result<Vec<_>, _>>()?;
                drop(stream);
                if precision == 0 {
                    // Validate every float output outside the timed section.
                    let mut stream = execute_stream(plan.clone(), ctx.task_ctx())?;
                    let mut offset = 0;
                    while let Some(batch) = stream.next().await {
                        let batch = batch?;
                        let output = batch
                            .column(0)
                            .as_any()
                            .downcast_ref::<Float64Array>()
                            .ok_or("expected Float64 quotient")?;
                        for (row, actual) in output.iter().enumerate() {
                            let i = offset + row;
                            let a = if numerator_scalar {
                                Some(3.0)
                            } else if nulls && i % 10 == 9 {
                                None
                            } else {
                                Some((i % 10000 + 2) as f64 / 100.0)
                            };
                            let b = if scalar {
                                Some(3.0)
                            } else if nulls && i % 13 == 12 {
                                None
                            } else {
                                Some((i % 97 + 3) as f64 / 100.0)
                            };
                            assert_eq!(actual, a.zip(b).map(|(a, b)| a / b), "{id}, row {i}");
                        }
                        offset += batch.num_rows();
                    }
                    assert_eq!(offset, ROWS);
                }
                for _ in 0..WARMUPS {
                    assert_eq!(consume(&ctx, plan.clone()).await?, (ROWS, expected_nulls));
                }
                let mut elapsed_ms = Vec::new();
                perf_command(b"enable\n")?;
                for _ in 0..SAMPLES {
                    let start = Instant::now();
                    let counts = consume(&ctx, plan.clone()).await?;
                    elapsed_ms.push(start.elapsed().as_secs_f64() * 1000.0);
                    assert_eq!(counts, (ROWS, expected_nulls));
                }
                perf_command(b"disable\n")?;
                let mut sorted = elapsed_ms.clone();
                sorted.sort_by(f64::total_cmp);
                let median_ms = sorted[SAMPLES / 2];
                eprintln!("{id}: {median_ms:.3} ms");
                results.push(json!({
                    "id": id, "sql": sql, "ansi": ansi,
                    "precision": precision, "scale": scale,
                    "nullable_input": nulls, "divisor_kind": divisor_kind,
                    "output_type": format!("{:?}", plan.schema().field(0).data_type()),
                    "output_nulls": expected_nulls, "first_values": first_values,
                    "physical_plan": physical_plan,
                    "samples_ms": elapsed_ms, "median_ms": median_ms,
                }));
            }
        }
    }
    if results.is_empty() {
        return Err("no benchmark case matched CASE_ID".into());
    }
    let capture: Value = json!({
        "rows": ROWS, "batch_size": BATCH_SIZE, "partitions": 1,
        "warmups": WARMUPS, "samples": SAMPLES, "results": results,
    });
    fs::write(output, serde_json::to_vec_pretty(&capture)?)?;
    Ok(())
}

sources.accepted_common:
// Modified from Sail v0.7.1 for the Delta reader experiment. See experiments/spark-sql/UPSTREAM.md in the host repository.
use std::sync::Arc;

use datafusion::arrow::datatypes::DataType;
use datafusion::logical_expr::expr::NullTreatment;
use datafusion::prelude::SessionContext;
use datafusion_common::tree_node::TreeNode;
use datafusion_common::{DFSchemaRef, ScalarValue};
use datafusion_expr::expr::{AggregateFunction, AggregateFunctionParams, WindowFunctionParams};
use datafusion_expr::{
    AggregateUDF, BinaryExpr, ExprSchemable, Operator, ScalarUDF, ScalarUDFImpl, WindowFrame,
    WindowFunctionDefinition, WindowUDF, cast, expr, lit, try_cast,
};
use sail_common_datafusion::utils::items::ItemTaker;
use sail_function::scalar::spark_cast_float_to_decimal::SparkCastFloatToDecimal;
use sail_function::scalar::spark_cast_string_to_decimal::SparkCastStringToDecimal;
use sail_function::scalar::variant::spark_cast_to_variant::SparkCastToVariant;
use sail_function::sketch::{DEFAULT_HLL_LG_CONFIG_K, DEFAULT_THETA_LG_NOM_ENTRIES};

use crate::config::PlanConfig;
use crate::error::{IntoPlanResult, PlanError, PlanResult};

pub struct FunctionContextInput<'a> {
    /// The names of function arguments.
    /// Most functions do not need this information, so it is
    /// passed as `&[String]` rather than `Vec<String>` to avoid unnecessary clone.
    /// These are the display names from the [`crate::resolver::expression::NamedExpr`]s,
    /// not to be confused with named function arguments
    /// (e.g., not like encode(charset => "utf-8", expr => "abc")).
    pub argument_display_names: &'a [String],
    pub plan_config: &'a Arc<PlanConfig>,
    pub session_context: &'a SessionContext,
    pub schema: &'a DFSchemaRef,
}

pub struct ScalarFunctionInput<'a> {
    pub arguments: Vec<expr::Expr>,
    pub function_context: FunctionContextInput<'a>,
}

pub(crate) type ScalarFunction =
    Arc<dyn Fn(ScalarFunctionInput) -> PlanResult<expr::Expr> + Send + Sync>;

pub(crate) struct ScalarFunctionBuilder;

impl ScalarFunctionBuilder {
    pub fn nullary<F, R>(f: F) -> ScalarFunction
    where
        F: Fn() -> R + Send + Sync + 'static,
        R: IntoPlanResult<expr::Expr>,
    {
        Arc::new(
            move |ScalarFunctionInput {
                      arguments,
                      function_context: _,
                  }| {
                arguments.zero()?;
                f().into_plan_result()
            },
        )
    }

    pub fn unary<F, R>(f: F) -> ScalarFunction
    where
        F: Fn(expr::Expr) -> R + Send + Sync + 'static,
        R: IntoPlanResult<expr::Expr>,
    {
        Arc::new(
            move |ScalarFunctionInput {
                      arguments,
                      function_context: _,
                  }| f(arguments.one()?).into_plan_result(),
        )
    }

    pub fn binary<F, R>(f: F) -> ScalarFunction
    where
        F: Fn(expr::Expr, expr::Expr) -> R + Send + Sync + 'static,
        R: IntoPlanResult<expr::Expr>,
    {
        Arc::new(
            move |ScalarFunctionInput {
                      arguments,
                      function_context: _,
                  }| {
                let (left, right) = arguments.two()?;
                f(left, right).into_plan_result()
            },
        )
    }

    pub fn ternary<F, R>(f: F) -> ScalarFunction
    where
        F: Fn(expr::Expr, expr::Expr, expr::Expr) -> R + Send + Sync + 'static,
        R: IntoPlanResult<expr::Expr>,
    {
        Arc::new(
            move |ScalarFunctionInput {
                      arguments,
                      function_context: _,
                  }| {
                let (first, second, third) = arguments.three()?;
                f(first, second, third).into_plan_result()
            },
        )
    }

    pub fn quaternary<F, R>(f: F) -> ScalarFunction
    where
        F: Fn(expr::Expr, expr::Expr, expr::Expr, expr::Expr) -> R + Send + Sync + 'static,
        R: IntoPlanResult<expr::Expr>,
    {
        Arc::new(
            move |ScalarFunctionInput {
                      arguments,
                      function_context: _,
                  }| {
                let (first, second, third, fourth) = arguments.four()?;
                f(first, second, third, fourth).into_plan_result()
            },
        )
    }

    pub fn var_arg<F, R>(f: F) -> ScalarFunction
    where
        F: Fn(Vec<expr::Expr>) -> R + Send + Sync + 'static,
        R: IntoPlanResult<expr::Expr>,
    {
        Arc::new(
            move |ScalarFunctionInput {
                      arguments,
                      function_context: _,
                  }| f(arguments).into_plan_result(),
        )
    }

    pub fn binary_op(op: Operator) -> ScalarFunction {
        Arc::new(
            move |ScalarFunctionInput {
                      arguments,
                      function_context,
                  }| {
                let (left, right) = arguments.two()?;
                spark_binary_expr(left, op, right, function_context.schema)
            },
        )
    }

    pub fn cast(data_type: DataType) -> ScalarFunction {
        Arc::new(
            move |ScalarFunctionInput {
                      arguments,
                      function_context,
                  }| {
                let arg = arguments.one()?;
                if let DataType::Decimal128(precision, scale) = data_type {
                    match arg.get_type(function_context.schema)? {
                        DataType::Utf8 | DataType::LargeUtf8 | DataType::Utf8View => {
                            return Ok(ScalarUDF::new_from_impl(SparkCastStringToDecimal::new(
                                precision,
                                scale,
                                !function_context.plan_config.ansi_mode,
                            ))
                            .call(vec![arg]));
                        }
                        DataType::Float32 | DataType::Float64 => {
                            return Ok(if function_context.plan_config.ansi_mode {
                                ScalarUDF::new_from_impl(SparkCastFloatToDecimal::new(
                                    precision, scale,
                                ))
                                .call(vec![arg])
                            } else {
                                try_cast(arg, data_type.clone())
                            });
                        }
                        _ => {}
                    }
                }
                Ok(cast(arg, data_type.clone()))
            },
        )
    }

    pub fn udf<F>(f: F) -> ScalarFunction
    where
        F: ScalarUDFImpl + Send + Sync + 'static,
    {
        let func = ScalarUDF::from(f);
        Arc::new(
            move |ScalarFunctionInput {
                      arguments,
                      function_context: _,
                  }| { Ok(func.call(arguments)) },
        )
    }

    pub fn custom<F>(f: F) -> ScalarFunction
    where
        F: Fn(ScalarFunctionInput) -> PlanResult<expr::Expr> + Send + Sync + 'static,
    {
        Arc::new(f)
    }

    pub fn unknown(name: &str) -> ScalarFunction {
        let name = name.to_string();
        Arc::new(move |_| Err(PlanError::todo(format!("function: {name}"))))
    }
}

pub(crate) fn spark_in_list(
    value: expr::Expr,
    list: Vec<expr::Expr>,
    negated: bool,
    schema: &DFSchemaRef,
) -> PlanResult<expr::Expr> {
    let mut input = expr::InList::new(Box::new(value), list, negated);
    let (mut decimal, mut floating, mut double) = (false, false, false);
    for value in std::iter::once(input.expr.as_ref()).chain(&input.list) {
        let data_type = value.get_type(schema)?;
        // Leave string promotion and non-numeric coercion to the existing path.
        if !data_type.is_numeric() && data_type != DataType::Null {
            return Ok(expr::Expr::InList(input));
        }
        decimal |= data_type.is_decimal();
        floating |= data_type.is_floating();
        double |= data_type == DataType::Float64;
    }
    if floating {
        // Only zero and NaN can change membership when the input is normalized.
        // ponytail: recognize literals and direct numeric literal casts only;
        // leave other constant expressions on the existing normalization path.
        let (mut zero, mut negative_zero) = (false, false);
        let known_without_nan = matches!(
            input.expr.get_type(schema)?,
            DataType::Float32 | DataType::Float64
        ) && input.list.iter().all(|value| {
            let scalar = match value {
                expr::Expr::Literal(value, _) => Some(value.clone()),
                expr::Expr::Cast(expr::Cast { expr, field })
                | expr::Expr::TryCast(expr::TryCast { expr, field }) => expr
                    .as_literal()
                    .filter(|value| value.data_type().is_numeric() || value.is_null())
                    .and_then(|value| value.cast_to(field.data_type()).ok()),
                _ => None,
            };
            match scalar.and_then(|value| match value {
                value @ ScalarValue::Float64(_) => Some(value),
                value => value.cast_to(&DataType::Float64).ok(),
            }) {
                Some(ScalarValue::Float64(value)) => value.is_none_or(|value| {
                    zero |= value == 0.0;
                    negative_zero |= value == 0.0 && value.is_sign_negative();
                    !value.is_nan()
                }),
                _ => false,
            }
        });
        let skip_normalization = known_without_nan && !zero;
        // Adding positive zero preserves NaNs and unifies both zero signs.
        // Keep computed operands and fused widening on their existing path.
        let zero_only = known_without_nan
            && zero
            && input.expr.try_as_col().is_some()
            && !(input.expr.get_type(schema)? == DataType::Float32 && (decimal || double));
        // Decimal/float lists use DOUBLE. Otherwise preserve operand types
        // so normalization does not change the existing numeric coercion.
        let convert = |value: expr::Expr, skip_normalization: bool| -> PlanResult<expr::Expr> {
            let data_type = value.get_type(schema)?;
            let floating = data_type.is_floating();
            Ok(if floating && !skip_normalization {
                ScalarUDF::from(SparkComparisonFloat {
                    widen: decimal || double,
                })
                .call(vec![value])
            } else if data_type != DataType::Float64 && (decimal || (floating && double)) {
                cast(value, DataType::Float64)
            } else {
                value
            })
        };
        input.expr = Box::new(if zero_only {
            let zero = ScalarValue::new_zero(&input.expr.get_type(schema)?)?;
            *input.expr + lit(zero)
        } else {
            convert(*input.expr, skip_normalization)?
        });
        input.list = input
            .list
            .into_iter()
            .map(|value| convert(value, known_without_nan && !negative_zero))
            .collect::<PlanResult<_>>()?;
    }
    Ok(expr::Expr::InList(input))
}

pub(crate) fn spark_binary_expr(
    mut left: expr::Expr,
    op: Operator,
    mut right: expr::Expr,
    schema: &DFSchemaRef,
) -> PlanResult<expr::Expr> {
    if matches!(
        op,
        Operator::Eq
            | Operator::NotEq
            | Operator::Lt
            | Operator::LtEq
            | Operator::Gt
            | Operator::GtEq
            | Operator::IsDistinctFrom
            | Operator::IsNotDistinctFrom
    ) {
        let left_type = left.get_type(schema)?;
        let right_type = right.get_type(schema)?;
        if (left_type.is_numeric() || left_type == DataType::Null)
            && (right_type.is_numeric() || right_type == DataType::Null)
        {
            let decimal_float = (left_type.is_decimal() && right_type.is_floating())
                || (left_type.is_floating() && right_type.is_decimal());
            let widen =
                decimal_float || left_type == DataType::Float64 || right_type == DataType::Float64;
            let convert = |value, data_type: DataType| {
                if data_type.is_floating() {
                    ScalarUDF::from(SparkComparisonFloat { widen }).call(vec![value])
                } else if decimal_float {
                    cast(value, DataType::Float64)
                } else {
                    value
                }
            };
            left = convert(left, left_type);
            right = convert(right, right_type);
        }
    }
    Ok(expr::Expr::BinaryExpr(BinaryExpr::new(
        Box::new(left),
        op,
        Box::new(right),
    )))
}

#[test]
fn in_list_skips_only_irrelevant_float_normalization() -> datafusion_common::Result<()> {
    use arrow::array::{Array, ArrayRef, AsArray, Float32Array, Float64Array};
    use arrow::datatypes::{Field, Float64Type, Schema};
    use arrow::record_batch::RecordBatch;
    use datafusion::optimizer::simplify_expressions::ExprSimplifier;
    use datafusion::physical_expr::{create_physical_expr, execution_props::ExecutionProps};
    use datafusion_common::{DFSchema, tree_node::TreeNodeRecursion};
    use datafusion_expr::{col, simplify::SimplifyContext};

    let half_schema = Arc::new(DFSchema::try_from(Schema::new(vec![Field::new(
        "v",
        DataType::Float16,
        true,
    )]))?);
    let half = spark_in_list(col("v"), vec![lit(1.25_f32)], false, &half_schema).unwrap();
    let expr::Expr::InList(half) = half else {
        unreachable!()
    };
    assert!(matches!(half.expr.as_ref(), expr::Expr::ScalarFunction(f)
        if f.func.inner().is::<SparkComparisonFloat>()));

    let cast_schema = Arc::new(DFSchema::try_from(Schema::new(vec![
        Field::new("decimal", DataType::Decimal128(18, 4), true),
        Field::new("integer", DataType::Int64, true),
    ]))?);
    for name in ["decimal", "integer"] {
        let expr::Expr::InList(input) = spark_in_list(
            cast(col(name), DataType::Float64),
            vec![lit(0.0_f64), lit(1.25_f64)],
            false,
            &cast_schema,
        )
        .unwrap() else {
            unreachable!()
        };
        assert_eq!(input.list.len(), 2, "preserve inverse-cast candidates");
        assert!(matches!(input.expr.as_ref(), expr::Expr::ScalarFunction(f)
            if f.func.inner().is::<SparkComparisonFloat>()));
    }

    let mut values = vec![
        None,
        Some(0.0),
        Some(-0.0),
        Some(1.25),
        Some(1.5),
        Some(-1.5),
        Some(f64::INFINITY),
        Some(f64::NEG_INFINITY),
        Some(f64::NAN),
        Some(f64::from_bits(0xfff0_0000_0000_0123)),
        Some(1e-40),
        Some(-1e-40),
    ];
    let mut bits = 0x1234_5678_9abc_def0_u64;
    values.extend((0..8192).map(|i| {
        bits = bits.wrapping_mul(6364136223846793005).wrapping_add(1);
        (i % 19 != 0).then_some(f64::from_bits(bits))
    }));
    let arrays: [ArrayRef; 2] = [
        Arc::new(Float32Array::from_iter(
            values.iter().map(|v| v.map(|v| v as f32)),
        )),
        Arc::new(Float64Array::from(values)),
    ];
    let mut checks = 0;
    let mut checked_rows = 0;
    for input in arrays {
        let ty = input.data_type().clone();
        let literal = |v: Option<f64>| {
            lit(match ty {
                DataType::Float32 => ScalarValue::Float32(v.map(|v| v as f32)),
                _ => ScalarValue::Float64(v),
            })
        };
        let finite = vec![Some(1.25), Some(1.5), Some(2.0)];
        let mut cases = vec![
            (
                "finite",
                finite.iter().copied().map(literal).collect::<Vec<_>>(),
                finite.clone(),
                true,
            ),
            (
                "nullable",
                vec![literal(Some(1.25)), literal(None)],
                vec![Some(1.25), None],
                true,
            ),
            (
                "zero",
                vec![literal(Some(0.0)), literal(Some(1.25))],
                vec![Some(0.0), Some(1.25)],
                true,
            ),
            (
                "negative_zero",
                vec![literal(Some(-0.0))],
                vec![Some(-0.0)],
                true,
            ),
            (
                "nan",
                vec![literal(Some(f64::NAN))],
                vec![Some(f64::NAN)],
                false,
            ),
            (
                "negative_nan",
                vec![literal(Some(-f64::NAN))],
                vec![Some(f64::NAN)],
                false,
            ),
            (
                "infinity",
                vec![
                    literal(Some(f64::INFINITY)),
                    literal(Some(f64::NEG_INFINITY)),
                ],
                vec![Some(f64::INFINITY), Some(f64::NEG_INFINITY)],
                true,
            ),
            ("all_null", vec![literal(None)], vec![None], true),
            ("empty", vec![], vec![], true),
            (
                "integer",
                vec![lit(1_i64), lit(2_i64)],
                vec![Some(1.0), Some(2.0)],
                true,
            ),
            (
                "decimal",
                vec![lit(ScalarValue::Decimal128(Some(125), 5, 2))],
                vec![Some(1.25)],
                true,
            ),
            (
                "casts",
                vec![cast(
                    lit(ScalarValue::Decimal128(Some(125), 5, 2)),
                    ty.clone(),
                )],
                vec![Some(1.25)],
                true,
            ),
            (
                "try_casts",
                vec![try_cast(lit(1_i64), ty.clone())],
                vec![Some(1.0)],
                true,
            ),
            (
                "underflow",
                vec![cast(lit(1e-50_f64), DataType::Float32)],
                vec![Some(0.0)],
                true,
            ),
            (
                "zero_nullable",
                vec![literal(Some(0.0)), literal(None)],
                vec![Some(0.0), None],
                true,
            ),
            (
                "zero_both_signs",
                vec![literal(Some(0.0)), literal(Some(-0.0))],
                vec![Some(0.0), Some(-0.0)],
                true,
            ),
            (
                "zero_integer",
                vec![lit(0_i64), lit(1_i64)],
                vec![Some(0.0), Some(1.0)],
                true,
            ),
            (
                "zero_decimal",
                vec![
                    lit(ScalarValue::Decimal128(Some(0), 5, 2)),
                    lit(ScalarValue::Decimal128(Some(125), 5, 2)),
                ],
                vec![Some(0.0), Some(1.25)],
                ty == DataType::Float64,
            ),
            (
                "zero_widening",
                vec![lit(0.0_f64), lit(1.25_f64)],
                vec![Some(0.0), Some(1.25)],
                ty == DataType::Float64,
            ),
            (
                "zero_negative_underflow",
                vec![cast(lit(-1e-50_f64), DataType::Float32)],
                vec![Some(-0.0)],
                true,
            ),
            (
                "zero_half",
                vec![cast(lit(0.0_f64), DataType::Float16)],
                vec![Some(0.0)],
                true,
            ),
            (
                "negative_zero_half",
                vec![cast(lit(-0.0_f64), DataType::Float16)],
                vec![Some(-0.0)],
                true,
            ),
            (
                "zero_nan",
                vec![literal(Some(0.0)), literal(Some(-f64::NAN))],
                vec![Some(0.0), Some(f64::NAN)],
                false,
            ),
            (
                "zero_unknown_cast",
                vec![literal(Some(0.0)), cast(lit("1.25"), ty.clone())],
                vec![Some(0.0), Some(1.25)],
                false,
            ),
            (
                "cast_nan",
                vec![cast(lit(-f64::NAN), DataType::Float32)],
                vec![Some(f64::NAN)],
                false,
            ),
            (
                "string_cast",
                vec![cast(lit("1.25"), ty.clone())],
                vec![Some(1.25)],
                false,
            ),
            (
                "nested_cast",
                vec![cast(cast(lit(1_i64), DataType::Float32), ty.clone())],
                vec![Some(1.0)],
                false,
            ),
            (
                "dynamic",
                vec![col("v"), literal(Some(1.25))],
                vec![Some(1.25)],
                false,
            ),
        ];
        let long: Vec<_> = (1..=128).map(|v| Some(f64::from(v))).collect();
        cases.push((
            "long",
            long.iter().copied().map(literal).collect(),
            long,
            true,
        ));
        let long_zero: Vec<_> = (0..=128).map(|v| Some(f64::from(v))).collect();
        cases.push((
            "zero_long",
            long_zero.iter().copied().map(literal).collect(),
            long_zero,
            true,
        ));
        for (offset, rows) in [(0, input.len()), (1, input.len() - 1), (2, 1), (0, 0)] {
            let input = input.slice(offset, rows);
            let schema = Arc::new(Schema::new(vec![Field::new("v", ty.clone(), true)]));
            let batch = RecordBatch::try_new(schema.clone(), vec![input.clone()])?;
            let schema = Arc::new(DFSchema::try_from(schema)?);
            let simplifier = ExprSimplifier::new(
                SimplifyContext::builder()
                    .with_schema(schema.clone())
                    .build(),
            );
            let wide = arrow::compute::cast(&input, &DataType::Float64)?;
            for (name, list, expected, skip) in &cases {
                for negated in [false, true] {
                    let candidate =
                        spark_in_list(col("v"), list.clone(), negated, &schema).unwrap();
                    let expr::Expr::InList(in_list) = &candidate else {
                        unreachable!()
                    };
                    let mut normalizers = 0;
                    in_list.expr.apply(|e| {
                        if let expr::Expr::ScalarFunction(f) = e {
                            normalizers += usize::from(f.func.inner().is::<SparkComparisonFloat>());
                        }
                        Ok(TreeNodeRecursion::Continue)
                    })?;
                    assert_eq!(normalizers, usize::from(!skip), "{ty} {name}");
                    assert_eq!(
                        in_list.list.len(),
                        list.len(),
                        "preserve native IN dispatch"
                    );
                    if matches!(*name, "zero" | "zero_nullable" | "zero_long") {
                        assert!(
                            in_list.list.iter().all(|value| {
                                !matches!(value, expr::Expr::ScalarFunction(f)
                                if f.func.inner().is::<SparkComparisonFloat>())
                            }),
                            "canonical constants do not need normalization: {ty} {name}"
                        );
                    }
                    if *skip && expected.contains(&Some(0.0)) {
                        assert!(
                            matches!(
                                in_list.expr.as_ref(),
                                expr::Expr::BinaryExpr(BinaryExpr {
                                    op: Operator::Plus,
                                    ..
                                })
                            ),
                            "{ty} {name}"
                        );
                    } else if *skip && ty == DataType::Float64 {
                        // An identity cast can hide native IN and inverse-Decimal rewrites.
                        assert_eq!(in_list.expr.as_ref(), &col("v"));
                    }
                    let normalized =
                        ScalarUDF::from(SparkComparisonFloat { widen: false }).call(vec![col("v")]);
                    let baseline =
                        spark_in_list(normalized, list.clone(), negated, &schema).unwrap();
                    assert_eq!(baseline.get_type(&schema)?, candidate.get_type(&schema)?);
                    assert_eq!(baseline.nullable(&schema)?, candidate.nullable(&schema)?);
                    for expression in [baseline, candidate] {
                        let expression =
                            simplifier.simplify(simplifier.coerce(expression, &schema)?)?;
                        let result =
                            create_physical_expr(&expression, &schema, &ExecutionProps::new())?
                                .evaluate(&batch)?
                                .into_array(rows)?;
                        for (i, value) in wide.as_primitive::<Float64Type>().iter().enumerate() {
                            let found = if expected.is_empty() && *name != "dynamic" {
                                Some(false)
                            } else {
                                value.and_then(|v| {
                                    if *name == "dynamic"
                                        || expected
                                            .iter()
                                            .flatten()
                                            .any(|w| v == *w || (v.is_nan() && w.is_nan()))
                                    {
                                        Some(true)
                                    } else if expected.contains(&None) {
                                        None
                                    } else {
                                        Some(false)
                                    }
                                })
                            }
                            .map(|v| v != negated);
                            assert_eq!(
                                result.as_boolean().is_null(i),
                                found.is_none(),
                                "{ty} {name} {i}"
                            );
                            if let Some(found) = found {
                                assert_eq!(result.as_boolean().value(i), found, "{ty} {name} {i}");
                            }
                            checked_rows += 1;
                        }
                        checks += 1;
                    }
                }
            }
        }
    }
    assert_eq!(checks, 960);
    assert_eq!(checked_rows, 3937920);
    Ok(())
}

#[derive(Debug, PartialEq, Eq, Hash)]
struct SparkComparisonFloat {
    widen: bool,
}

impl ScalarUDFImpl for SparkComparisonFloat {
    fn name(&self) -> &str {
        "spark_comparison_float"
    }

    fn signature(&self) -> &datafusion_expr::Signature {
        static SIGNATURE: std::sync::LazyLock<datafusion_expr::Signature> =
            std::sync::LazyLock::new(|| {
                datafusion_expr::Signature::uniform(
                    1,
                    vec![DataType::Float32, DataType::Float64],
                    datafusion_expr::Volatility::Immutable,
                )
            });
        &SIGNATURE
    }

    fn return_type(&self, args: &[DataType]) -> datafusion_common::Result<DataType> {
        Ok(if self.widen {
            DataType::Float64
        } else {
            args[0].clone()
        })
    }

    fn return_field_from_args(
        &self,
        args: datafusion_expr::ReturnFieldArgs,
    ) -> datafusion_common::Result<arrow::datatypes::FieldRef> {
        Ok(Arc::new(arrow::datatypes::Field::new(
            self.name(),
            self.return_type(&[args.arg_fields[0].data_type().clone()])?,
            args.arg_fields[0].is_nullable(),
        )))
    }

    fn simplify(
        &self,
        args: Vec<expr::Expr>,
        info: &datafusion_expr::simplify::SimplifyContext,
    ) -> datafusion_common::Result<datafusion_expr::simplify::ExprSimplifyResult> {
        use datafusion_expr::simplify::ExprSimplifyResult;
        let canonical = match &args[0] {
            expr::Expr::ScalarFunction(f) => f.func.inner().is::<Self>(),
            expr::Expr::Cast(expr::Cast { expr, field })
            | expr::Expr::TryCast(expr::TryCast { expr, field }) => {
                let source = info.get_data_type(expr)?;
                // Integer casts cannot produce -0 or NaN. Decimal-to-DOUBLE
                // cannot underflow; Decimal-to-FLOAT can, so keep its check.
                source.is_integer()
                    || (source.is_decimal() && field.data_type() == &DataType::Float64)
            }
            _ => false,
        };
        if !canonical {
            return Ok(ExprSimplifyResult::Original(args));
        }
        let [arg] = datafusion_common::utils::take_function_args(self.name(), args)?;
        Ok(ExprSimplifyResult::Simplified(
            if self.widen && info.get_data_type(&arg)? == DataType::Float32 {
                cast(arg, DataType::Float64)
            } else {
                arg
            },
        ))
    }

    fn invoke_with_args(
        &self,
        input: datafusion_expr::ScalarFunctionArgs,
    ) -> datafusion_common::Result<datafusion_expr::ColumnarValue> {
        use arrow::array::AsArray;
        use arrow::datatypes::{Float32Type, Float64Type};
        use datafusion_expr::ColumnarValue;
        // Fuse FLOAT widening with normalization; evaluate the operand once.
        // Adding positive zero clears the sign of -0; NaNs still need explicit canonicalization.
        let normalize = |v: f64| {
            if v.is_nan() { f64::NAN } else { v + 0.0 }
        };
        let [value] = datafusion_common::utils::take_function_args(self.name(), input.args)?;
        if !self.widen && value.data_type() == DataType::Float32 {
            let normalize = |v: f32| {
                if v.is_nan() { f32::NAN } else { v + 0.0 }
            };
            return Ok(match value {
                ColumnarValue::Scalar(ScalarValue::Float32(v)) => {
                    ColumnarValue::Scalar(ScalarValue::Float32(v.map(normalize)))
                }
                ColumnarValue::Array(a) => ColumnarValue::Array(Arc::new(
                    a.as_primitive::<Float32Type>()
                        .unary::<_, Float32Type>(normalize),
                )),
                _ => unreachable!("FLOAT operand checked above"),
            });
        }
        Ok(match value {
            ColumnarValue::Scalar(ScalarValue::Float32(v)) => {
                ColumnarValue::Scalar(ScalarValue::Float64(v.map(|v| normalize(f64::from(v)))))
            }
            ColumnarValue::Scalar(ScalarValue::Float64(v)) => {
                ColumnarValue::Scalar(ScalarValue::Float64(v.map(normalize)))
            }
            ColumnarValue::Array(a) if a.data_type() == &DataType::Float32 => {
                ColumnarValue::Array(Arc::new(
                    a.as_primitive::<Float32Type>()
                        .unary::<_, Float64Type>(|v| normalize(f64::from(v))),
                ))
            }
            ColumnarValue::Array(a) if a.data_type() == &DataType::Float64 => {
                ColumnarValue::Array(Arc::new(
                    a.as_primitive::<Float64Type>()
                        .unary::<_, Float64Type>(normalize),
                ))
            }
            _ => {
                return datafusion_common::internal_err!(
                    "expected FLOAT or DOUBLE comparison operand"
                );
            }
        })
    }
}

#[test]
fn comparison_float_preserves_values_nulls_and_shapes() -> datafusion_common::Result<()> {
    use arrow::array::{Array, ArrayRef, AsArray, Float32Array, Float64Array};
    use arrow::datatypes::{Field, Float64Type};
    use datafusion_common::config::ConfigOptions;
    use datafusion_expr::{ColumnarValue, ScalarFunctionArgs};
    let run = |value: ColumnarValue, rows, widen| {
        let return_type = if widen {
            DataType::Float64
        } else {
            value.data_type()
        };
        SparkComparisonFloat { widen }.invoke_with_args(ScalarFunctionArgs {
            arg_fields: vec![Arc::new(Field::new("x", value.data_type(), true))],
            args: vec![value],
            number_rows: rows,
            return_field: Arc::new(Field::new("x", return_type, true)),
            config_options: Arc::new(ConfigOptions::default()),
        })
    };
    let values = [
        Some(-0.0),
        Some(0.0),
        None,
        Some(-0.1),
        Some(0.1),
        Some(f64::INFINITY),
        Some(f64::NEG_INFINITY),
        Some(f64::NAN),
        Some(-f64::NAN),
        Some(f64::from_bits(0x7ff0_0000_0000_0001)),
        Some(f64::from_bits(0xfff0_0000_0000_1234)),
        Some(1e-40),
        Some(-1e-40),
    ];
    let arrays: [ArrayRef; 2] = [
        Arc::new(Float32Array::from_iter(values.map(|v| v.map(|v| v as f32)))),
        Arc::new(Float64Array::from_iter(values)),
    ];
    let mut arrays = arrays.to_vec();
    // Exercise IEEE boundaries and arbitrary bit patterns without a random dependency.
    let mut bits = vec![
        0,
        1,
        0x000f_ffff_ffff_ffff,
        0x0010_0000_0000_0000,
        0x7fef_ffff_ffff_ffff,
        0x7ff0_0000_0000_0000,
        0x7ff0_0000_0000_0001,
        0x7ff8_0000_0000_0000,
        0x7fff_ffff_ffff_ffff,
        0x0000_0001_0000_0000,
        0x007f_ffff_0000_0000,
        0x0080_0000_0000_0000,
        0x7f7f_ffff_0000_0000,
        0x7f80_0000_0000_0000,
        0x7f80_0001_0000_0000,
        0x7fc0_0000_0000_0000,
        0x7fff_ffff_0000_0000,
    ];
    bits.extend(bits.clone().into_iter().map(|v| v | (1 << 63)));
    let mut state = 0x1234_5678_9abc_def0_u64;
    bits.extend((0..8192).map(|_| {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        state
    }));
    arrays.push(Arc::new(Float32Array::from_iter(
        bits.iter()
            .enumerate()
            .map(|(i, &v)| (i % 19 != 18).then_some(f32::from_bits((v >> 32) as u32))),
    )));
    arrays.push(Arc::new(Float64Array::from_iter(
        bits.iter()
            .enumerate()
            .map(|(i, &v)| (i % 19 != 18).then_some(f64::from_bits(v))),
    )));
    for input in arrays {
        for widen in [false, true] {
            for (offset, len) in [(0, input.len()), (1, 10), (1, input.len() - 1), (0, 0)] {
                let input = input.slice(offset, len);
                let output =
                    run(ColumnarValue::Array(input.clone()), len, widen)?.into_array(len)?;
                assert_eq!(
                    output.data_type(),
                    if widen {
                        &DataType::Float64
                    } else {
                        input.data_type()
                    }
                );
                let output = arrow::compute::cast(&output, &DataType::Float64)?;
                let actual = output.as_primitive::<Float64Type>();
                let widened = arrow::compute::cast(&input, &DataType::Float64)?;
                for (i, value) in widened.as_primitive::<Float64Type>().iter().enumerate() {
                    let expected = value.map(|v| {
                        if v.is_nan() {
                            f64::NAN.to_bits()
                        } else if v == 0.0 {
                            0
                        } else {
                            v.to_bits()
                        }
                    });
                    assert_eq!(actual.is_null(i), expected.is_none());
                    if let Some(bits) = expected {
                        assert_eq!(actual.value(i).to_bits(), bits);
                    }
                    let scalar = ScalarValue::try_from_array(&input, i)?;
                    let ColumnarValue::Scalar(result) =
                        run(ColumnarValue::Scalar(scalar), 1, widen)?
                    else {
                        panic!("expected scalar")
                    };
                    assert_eq!(
                        result.data_type(),
                        if widen {
                            DataType::Float64
                        } else {
                            input.data_type().clone()
                        }
                    );
                    let ScalarValue::Float64(result) = result.cast_to(&DataType::Float64)? else {
                        panic!("expected floating scalar")
                    };
                    assert_eq!(result.map(f64::to_bits), expected);
                }
            }
        }
    }
    Ok(())
}

/// Aggregate function input components, excluding the function name.
///
/// Populated by the resolver from `spec::UnresolvedFunction` after resolving spec expressions
/// to DataFusion expressions. Used by aggregate function builders to produce the final
/// DataFusion aggregate expression.
pub struct AggFunctionInput<'a> {
    pub arguments: Vec<expr::Expr>,
    pub distinct: bool,
    pub ignore_nulls: Option<bool>,
    pub filter: Option<Box<expr::Expr>>,
    pub order_by: Vec<expr::Sort>,
    pub function_context: FunctionContextInput<'a>,
}

/// Builds a DataFusion aggregate expression from resolved function components.
///
/// Takes the resolved arguments, modifiers (DISTINCT, FILTER, ORDER BY), and context,
/// and produces a `datafusion_expr::Expr::AggregateFunction` ready for inclusion in the logical plan.
pub(crate) type AggFunction = Arc<dyn Fn(AggFunctionInput) -> PlanResult<expr::Expr> + Send + Sync>;

/// Factory methods for creating `AggFunction`s.
///
/// Provides different ways to build aggregate function handlers:
/// - `default`: Use an existing DataFusion UDAF directly
/// - `custom`: Provide custom logic for building the expression
/// - `unknown`: Placeholder for unimplemented functions
pub(crate) struct AggFunctionBuilder;

impl AggFunctionBuilder {
    /// Converts a DataFusion UDAF factory into an AggFunction.
    ///
    /// Passes all resolved components through directly with no transformation.
    pub fn default<F>(f: F) -> AggFunction
    where
        F: Fn() -> Arc<AggregateUDF> + Send + Sync + 'static,
    {
        Arc::new(move |input| {
            let AggFunctionInput {
                arguments,
                distinct,
                ignore_nulls,
                filter,
                order_by,
                function_context: _function_context,
            } = input;
            let null_treatment = get_null_treatment(ignore_nulls);
            Ok(expr::Expr::AggregateFunction(AggregateFunction {
                func: f(),
                params: AggregateFunctionParams {
                    args: arguments,
                    distinct,
                    filter,
                    order_by,
                    null_treatment,
                },
            }))
        })
    }

    /// Wraps a custom function that builds the aggregate expression with full control.
    ///
    /// Use when the function needs special argument handling that `default` cannot provide.
    pub fn custom<F>(f: F) -> AggFunction
    where
        F: Fn(AggFunctionInput) -> PlanResult<expr::Expr> + Send + Sync + 'static,
    {
        Arc::new(f)
    }

    pub fn unknown(name: &str) -> AggFunction {
        let name = name.to_string();
        Arc::new(move |_| Err(PlanError::todo(format!("function: {name}"))))
    }
}

pub struct WinFunctionInput<'a> {
    pub arguments: Vec<expr::Expr>,
    pub partition_by: Vec<expr::Expr>,
    pub order_by: Vec<expr::Sort>,
    pub window_frame: WindowFrame,
    pub ignore_nulls: Option<bool>,
    pub distinct: bool,
    pub function_context: FunctionContextInput<'a>,
}

pub(crate) type WinFunction = Arc<dyn Fn(WinFunctionInput) -> PlanResult<expr::Expr> + Send + Sync>;

pub(crate) struct WinFunctionBuilder;

impl WinFunctionBuilder {
    pub fn aggregate<F>(f: F) -> WinFunction
    where
        F: Fn() -> Arc<AggregateUDF> + Send + Sync + 'static,
    {
        Arc::new(move |input| {
            let WinFunctionInput {
                arguments,
                partition_by,
                order_by,
                window_frame,
                ignore_nulls,
                distinct,
                function_context: _function_context,
            } = input;
            let null_treatment = get_null_treatment(ignore_nulls);
            Ok(expr::Expr::WindowFunction(Box::new(expr::WindowFunction {
                fun: WindowFunctionDefinition::AggregateUDF(f()),
                params: WindowFunctionParams {
                    args: arguments,
                    partition_by,
                    order_by,
                    window_frame,
                    filter: None,
                    null_treatment,
                    distinct,
                },
            })))
        })
    }

    pub fn window<F>(f: F) -> WinFunction
    where
        F: Fn() -> Arc<WindowUDF> + Send + Sync + 'static,
    {
        Arc::new(move |input| {
            let WinFunctionInput {
                arguments,
                partition_by,
                order_by,
                window_frame,
                ignore_nulls,
                distinct,
                function_context,
            } = input;
            let null_treatment = get_null_treatment(ignore_nulls);
            let win_func_expr = expr::Expr::WindowFunction(Box::new(expr::WindowFunction {
                fun: WindowFunctionDefinition::WindowUDF(f()),
                params: WindowFunctionParams {
                    args: arguments,
                    partition_by,
                    order_by,
                    window_frame,
                    filter: None,
                    null_treatment,
                    distinct,
                },
            }));
            Ok(match win_func_expr.get_type(function_context.schema)? {
                DataType::UInt64 => cast(win_func_expr.clone(), DataType::Int32),
                _ => win_func_expr,
            })
        })
    }

    pub fn custom<F>(f: F) -> WinFunction
    where
        F: Fn(WinFunctionInput) -> PlanResult<expr::Expr> + Send + Sync + 'static,
    {
        Arc::new(f)
    }

    pub fn unknown(name: &str) -> WinFunction {
        let name = name.to_string();
        Arc::new(move |_| Err(PlanError::todo(format!("unknown window function: {name}"))))
    }
}

pub(crate) fn get_null_treatment(ignore_nulls: Option<bool>) -> Option<NullTreatment> {
    match ignore_nulls {
        Some(true) => Some(NullTreatment::IgnoreNulls),
        Some(false) => Some(NullTreatment::RespectNulls),
        None => None,
    }
}

pub(crate) fn get_arguments_and_null_treatment(
    args: Vec<expr::Expr>,
    ignore_nulls: Option<bool>,
) -> PlanResult<(Vec<expr::Expr>, Option<NullTreatment>)> {
    if args.len() == 1 {
        let expr = args.one()?;
        Ok((vec![expr], get_null_treatment(ignore_nulls)))
    } else if args.len() == 2 {
        if ignore_nulls.is_some() {
            return Err(PlanError::invalid(
                "arguments conflict with IGNORE NULLS clause",
            ));
        }
        let (expr, ignore_nulls) = args.two()?;
        let null_treatment = match ignore_nulls {
            expr::Expr::Literal(ScalarValue::Boolean(Some(ignore_nulls)), _metadata) => {
                if ignore_nulls {
                    Some(NullTreatment::IgnoreNulls)
                } else {
                    Some(NullTreatment::RespectNulls)
                }
            }
            _ => {
                return Err(PlanError::invalid(
                    "requires a boolean literal as the second argument",
                ));
            }
        };
        Ok((vec![expr], null_treatment))
    } else {
        Err(PlanError::invalid("requires 1 or 2 arguments"))
    }
}

pub(crate) fn hll_args_with_default_lg(
    arguments: Vec<expr::Expr>,
    function_name: &str,
) -> PlanResult<Vec<expr::Expr>> {
    match arguments.len() {
        1 => {
            let value = arguments.one()?;
            Ok(vec![value, lit(DEFAULT_HLL_LG_CONFIG_K)])
        }
        2 => {
            let (value, lg_config_k) = arguments.two()?;
            Ok(vec![value, cast(lg_config_k, DataType::Int32)])
        }
        count => Err(PlanError::invalid(format!(
            "{function_name} requires 1 or 2 arguments, got {count}"
        ))),
    }
}

pub(crate) fn hll_union_args_with_default_allow_different_lg(
    arguments: Vec<expr::Expr>,
) -> PlanResult<Vec<expr::Expr>> {
    match arguments.len() {
        1 => {
            let value = arguments.one()?;
            Ok(vec![value, lit(false)])
        }
        2 => {
            let (value, allow_different_lg_config_k) = arguments.two()?;
            Ok(vec![
                value,
                cast(allow_different_lg_config_k, DataType::Boolean),
            ])
        }
        count => Err(PlanError::invalid(format!(
            "hll_union_agg requires 1 or 2 arguments, got {count}"
        ))),
    }
}

pub(crate) fn count_min_sketch_args(arguments: Vec<expr::Expr>) -> PlanResult<Vec<expr::Expr>> {
    match arguments.len() {
        4 => {
            let (value, eps, confidence, seed) = arguments.four()?;
            // Spark requires `eps` and `confidence` to be DOUBLE literals and rejects
            // other types (including DECIMAL/FLOAT). Pass them through unchanged so the
            // aggregate's type validation enforces the same rule, instead of casting and
            // silently accepting types Spark rejects.
            Ok(vec![value, eps, confidence, seed])
        }
        count => Err(PlanError::invalid(format!(
            "count_min_sketch requires 4 arguments, got {count}"
        ))),
    }
}

pub(crate) fn theta_args_with_default_lg(
    arguments: Vec<expr::Expr>,
    function_name: &str,
) -> PlanResult<Vec<expr::Expr>> {
    match arguments.len() {
        1 => {
            let value = arguments.one()?;
            Ok(vec![value, lit(DEFAULT_THETA_LG_NOM_ENTRIES)])
        }
        2 => {
            let (value, lg_nom_entries) = arguments.two()?;
            Ok(vec![value, cast(lg_nom_entries, DataType::Int32)])
        }
        count => Err(PlanError::invalid(format!(
            "{function_name} requires 1 or 2 arguments, got {count}"
        ))),
    }
}

// TODO: Match Catalyst constant folding and NullPropagation before extracting opaque
//  Variant scalar calls, so a foldable NULL can eliminate them.
pub fn expr_contains_spark_cast_to_variant(body: &expr::Expr) -> PlanResult<bool> {
    Ok(body.exists(|expression| {
        Ok(matches!(
            expression,
            expr::Expr::ScalarFunction(function)
                if function.func.inner().is::<SparkCastToVariant>()
        ))
    })?)
}

#[test]
fn comparison_float_simplifies_only_canonical_inputs() -> datafusion_common::Result<()> {
    use arrow::array::{
        ArrayRef, Decimal32Array, Decimal64Array, Decimal128Array, Decimal256Array, Float32Array,
        Float64Array, Int64Array, UInt64Array,
    };
    use arrow::datatypes::{Field, Schema};
    use arrow::record_batch::RecordBatch;
    use datafusion::physical_expr::{create_physical_expr, execution_props::ExecutionProps};
    use datafusion_common::{DFSchema, scalar::ScalarValue};
    use datafusion_expr::col;
    use datafusion_expr::simplify::{ExprSimplifyResult, SimplifyContext};

    let mut arrays: Vec<ArrayRef> = vec![
        Arc::new(Int64Array::from(vec![
            Some(i64::MIN),
            Some(-1),
            Some(0),
            Some(1),
            Some(i64::MAX),
            None,
        ])),
        Arc::new(UInt64Array::from(vec![
            Some(0),
            Some(1),
            Some(u64::MAX),
            None,
        ])),
        Arc::new(Float32Array::from(vec![
            Some(-0.0),
            Some(f32::from_bits(0xffc00001)),
            Some(1.5),
            None,
        ])),
        Arc::new(Float64Array::from(vec![
            Some(-0.0),
            Some(f64::from_bits(0xfff8000000000001)),
            Some(1.5),
            None,
        ])),
    ];
    for data_type in [
        DataType::Int8,
        DataType::Int16,
        DataType::Int32,
        DataType::UInt8,
        DataType::UInt16,
        DataType::UInt32,
    ] {
        arrays.push(arrow::compute::cast(arrays[0].as_ref(), &data_type)?);
    }
    for scale in [-128, 0, 9] {
        arrays.push(Arc::new(
            Decimal32Array::from(vec![
                Some(-999_999_999),
                Some(-1),
                Some(0),
                Some(1),
                Some(999_999_999),
                None,
            ])
            .with_precision_and_scale(9, scale)?,
        ));
    }
    for scale in [-128, 0, 18] {
        arrays.push(Arc::new(
            Decimal64Array::from(vec![
                Some(-999_999_999_999_999_999),
                Some(-1),
                Some(0),
                Some(1),
                Some(999_999_999_999_999_999),
                None,
            ])
            .with_precision_and_scale(18, scale)?,
        ));
    }
    for scale in [-128, 0, 38] {
        let max = 10_i128.pow(38) - 1;
        arrays.push(Arc::new(
            Decimal128Array::from(vec![
                Some(-max),
                Some(-1),
                Some(0),
                Some(1),
                Some(max),
                None,
            ])
            .with_precision_and_scale(38, scale)?,
        ));
    }
    for scale in [-128, 0, 76] {
        let max = "9".repeat(76).parse::<arrow::datatypes::i256>().unwrap();
        arrays.push(Arc::new(
            Decimal256Array::from(vec![
                Some(-max),
                Some(arrow::datatypes::i256::from_i128(-1)),
                Some(arrow::datatypes::i256::ZERO),
                Some(arrow::datatypes::i256::ONE),
                Some(max),
                None,
            ])
            .with_precision_and_scale(76, scale)?,
        ));
    }
    for input in arrays {
        let schema = Arc::new(Schema::new(vec![Field::new(
            "v",
            input.data_type().clone(),
            true,
        )]));
        let batch = RecordBatch::try_new(schema.clone(), vec![input.clone()])?;
        let schema = Arc::new(DFSchema::try_from(schema)?);
        let info = SimplifyContext::builder()
            .with_schema(schema.clone())
            .build();
        for data_type in [DataType::Float32, DataType::Float64] {
            for safe in [false, true] {
                let cast = if safe {
                    try_cast(col("v"), data_type.clone())
                } else {
                    cast(col("v"), data_type.clone())
                };
                for nested in [false, true] {
                    let arg = if nested {
                        ScalarUDF::from(SparkComparisonFloat { widen: false })
                            .call(vec![cast.clone()])
                    } else {
                        cast.clone()
                    };
                    for widen in [false, true] {
                        let function = ScalarUDF::from(SparkComparisonFloat { widen });
                        let original = function.call(vec![arg.clone()]);
                        let result = function.simplify(vec![arg.clone()], &info)?;
                        let should_simplify = nested
                            || input.data_type().is_integer()
                            || (input.data_type().is_decimal() && data_type == DataType::Float64);
                        assert_eq!(
                            matches!(&result, ExprSimplifyResult::Simplified(_)),
                            should_simplify
                        );
                        let simplified = match result {
                            ExprSimplifyResult::Simplified(e) => e,
                            ExprSimplifyResult::Original(args) => function.call(args),
                        };
                        assert_eq!(original.get_type(&schema)?, simplified.get_type(&schema)?);
                        assert_eq!(original.nullable(&schema)?, simplified.nullable(&schema)?);
                        let evaluate = |e: &expr::Expr| {
                            create_physical_expr(e, &schema, &ExecutionProps::new())?
                                .evaluate(&batch)?
                                .into_array(batch.num_rows())
                        };
                        let a = evaluate(&original)?;
                        let b = evaluate(&simplified)?;
                        for i in 0..batch.num_rows() {
                            let bits =
                                |array: &ArrayRef| -> datafusion_common::Result<Option<u64>> {
                                    let ScalarValue::Float64(value) =
                                        ScalarValue::try_from_array(array, i)?
                                            .cast_to(&DataType::Float64)?
                                    else {
                                        unreachable!()
                                    };
                                    Ok(value.map(f64::to_bits))
                                };
                            assert_eq!(
                                bits(&a)?,
                                bits(&b)?,
                                "input={}, target={data_type}, safe={safe}, nested={nested}, widen={widen}, row={i}",
                                input.data_type()
                            );
                        }
                    }
                }
            }
        }
    }
    Ok(())
}

